// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Img, random } from '../remotionShim';


export type NetworkAnimationProps = Record<string, any>;

const getWirePath = (startX: number, startY: number, endX: number, endY: number) => {
  const diffX = endX - startX;
  const controlPointOffset = Math.max(diffX * 0.5, 50);
  return `M ${startX} ${startY} C ${startX + controlPointOffset} ${startY}, ${endX - controlPointOffset} ${endY}, ${endX} ${endY}`;
};

const getWireLength = (startX: number, startY: number, endX: number, endY: number) => {
  // Manhattan distance provides a safe upper bound for drawing the monotonic bezier curves fully.
  return Math.abs(endX - startX) + Math.abs(endY - startY);
};

const NetworkAnimation: React.FC<NetworkAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  shopifyLogo = "https://cdn.simpleicons.org/shopify/95BF47",
  instagramLogo = "https://cdn.simpleicons.org/instagram/E4405F",
  facebookLogo = "https://cdn.simpleicons.org/facebook/1877F2",
  tiktokLogo = "https://cdn.simpleicons.org/tiktok/000000",
  googleLogo = "https://cdn.simpleicons.org/google/4285F4",
  wireColor = "#4ade80",
  peopleColor = "#ffffff",
  peopleCount = 300,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Static Layout Nodes
  const shopifyNode = useMemo(() => ({ x: width * 0.15, y: height * 0.5 }), [width, height]);

  const socialNodes = useMemo(() => [
    { id: 'instagram', logo: instagramLogo, x: width * 0.5, y: height * 0.2 },
    { id: 'facebook', logo: facebookLogo, x: width * 0.5, y: height * 0.4 },
    { id: 'tiktok', logo: tiktokLogo, x: width * 0.5, y: height * 0.6 },
    { id: 'google', logo: googleLogo, x: width * 0.5, y: height * 0.8 },
  ], [instagramLogo, facebookLogo, tiktokLogo, googleLogo, width, height]);

  const peopleNodes = useMemo(() => {
    return Array.from({ length: peopleCount }).map((_, i) => {
      const socialIndex = i % 4;
      const x = width * 0.75 + random(`px-${i}`) * width * 0.2; 
      const y = height * 0.1 + random(`py-${i}`) * height * 0.8;
      return { id: i, x, y, socialIndex };
    });
  }, [peopleCount, width, height]);

  // Origin Node Animation
  const shopifyScale = spring({ frame, fps, config: { damping: 12 } });
  const shopifyOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Background SVG for all wires and people dots (Massively improves performance over individual divs) */}
      <svg style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible" }}>
        
        {/* Tier 1: Wires from Shopify to Socials */}
        {socialNodes.map((social, i) => {
          const wire1Start = 15 + i * 5; 
          const wire1End = wire1Start + 30;
          const wire1Progress = interpolate(frame, [wire1Start, wire1End], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
          
          const path = getWirePath(shopifyNode.x, shopifyNode.y, social.x, social.y);
          const len = getWireLength(shopifyNode.x, shopifyNode.y, social.x, social.y);
          
          return (
            <path
              key={`wire1-${i}`}
              d={path}
              fill="none"
              stroke={wireColor}
              strokeWidth={4}
              strokeDasharray={len}
              strokeDashoffset={len * (1 - wire1Progress)}
              opacity={0.6}
              style={{ transition: "none" }}
            />
          );
        })}
        
        {/* Tier 2: Wires from Socials to People & People Figures */}
        {peopleNodes.map((person) => {
          const social = socialNodes[person.socialIndex];
          
          // Ties the child stagger organically to the parent social node appearance
          const parentStagger = person.socialIndex * 5;
          const wire2Start = 110 + parentStagger + random(`w2-stagger-${person.id}`) * 15;
          const wire2End = wire2Start + 30;
          const pWireProgress = interpolate(frame, [wire2Start, wire2End], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

          const path = getWirePath(social.x, social.y, person.x, person.y);
          const len = getWireLength(social.x, social.y, person.x, person.y);
          
          const personStart = wire2End - 5; // Figure appears just as wire connects
          const pScale = spring({ frame: Math.max(0, frame - personStart), fps, config: { damping: 12 } });
          const pOpacity = interpolate(frame, [personStart, personStart + 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

          return (
            <React.Fragment key={`network-cluster-${person.id}`}>
              <path
                d={path}
                fill="none"
                stroke={wireColor}
                strokeWidth={1.5}
                strokeDasharray={len}
                strokeDashoffset={len * (1 - pWireProgress)}
                opacity={0.3}
                style={{ transition: "none" }}
              />
              <g
                transform={`translate(${person.x}, ${person.y}) scale(${pScale})`}
                fill={peopleColor}
                opacity={pOpacity}
                style={{ transition: "none", filter: `drop-shadow(0px 0px 4px ${peopleColor})` }}
              >
                <circle cx="0" cy="-2.5" r="2.5" />
                <path d="M -4.5 4.5 C -4.5 1, 4.5 1, 4.5 4.5 Z" />
              </g>
            </React.Fragment>
          );
        })}
      </svg>

      {/* Main Shopify Logo Layer */}
      <div
        style={{
          position: "absolute",
          left: shopifyNode.x - 100, 
          top: shopifyNode.y - 100,
          width: 200,
          height: 200,
          opacity: shopifyOpacity,
          transform: `scale(${shopifyScale})`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          backgroundColor: "#ffffff",
          borderRadius: "50%",
          boxShadow: "0 10px 40px rgba(0,0,0,0.4)",
          transition: "none",
        }}
      >
        <Img src={shopifyLogo} style={{ width: 110, height: 110, objectFit: "contain", transition: "none" }} />
      </div>

      {/* Social Media Logos Layer */}
      {socialNodes.map((social, i) => {
        const socialStart = 35 + i * 5;
        const sScale = spring({ frame: Math.max(0, frame - socialStart), fps, config: { damping: 12 } });
        const sOpacity = interpolate(frame, [socialStart, socialStart + 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
        
        return (
          <div
            key={`social-node-${social.id}`}
            style={{
              position: "absolute",
              left: social.x - 50, 
              top: social.y - 50,
              width: 100,
              height: 100,
              opacity: sOpacity,
              transform: `scale(${sScale})`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              backgroundColor: "#ffffff",
              borderRadius: "50%",
              boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
              transition: "none",
            }}
          >
            <Img src={social.logo} style={{ width: 60, height: 60, objectFit: "contain", transition: "none" }} />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default NetworkAnimation;